INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Services > Rechte
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Services immer mit Administratorrechten laufen, um funktional zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Viele Services laufen mit eingeschränkten Rechten"}, {"text": "Ja", "correct": false, "because": "Administratorrechte sind nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können falsch konfigurierte Rechte den Zugriff eines Services auf notwendige Ressourcen verhindern?', 2, '[{"text": "Ja", "correct": true, "because": "Fehlende Rechte blockieren Zugriff"}, {"text": "Nein", "correct": false, "because": "Rechte sind entscheidend für Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, einem Service mehr Rechte zuzuweisen, als für seine Funktion erforderlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch möglich, aber unsicher"}, {"text": "Nein", "correct": false, "because": "Übermäßige Rechte sind vermeidbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Rechte für Services unabhängig von der Benutzerkonfiguration des Systems?', 2, '[{"text": "Nein", "correct": true, "because": "Rechte hängen vom Systemkontext ab"}, {"text": "Ja", "correct": false, "because": "Benutzerkonfiguration beeinflusst Rechte"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Services ohne spezifische Rechte sicherheitsrelevante Aufgaben ausführen?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheitsaufgaben erfordern Zugriffsrechte"}, {"text": "Ja", "correct": false, "because": "Ohne Rechte ist Sicherheit eingeschränkt"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wird beim Zuweisen von Rechten an Services empfohlen?', 3, '[{"text": "Least Privilege", "correct": true, "because": "Minimiert Sicherheitsrisiken"}, {"text": "Full Access", "correct": false, "because": "Erhöht Risiken unnötig"}, {"text": "Random Assignment", "correct": false, "because": "Unstrukturiert und unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Betriebssystem verwaltet Service-Rechte oft über Benutzerkonten und Gruppen?', 2, '[{"text": "Linux", "correct": true, "because": "Nutzt Benutzer- und Gruppenrechte"}, {"text": "Windows", "correct": false, "because": "Nutzt auch Dienste-Konten"}, {"text": "macOS", "correct": false, "because": "Ähnlich, aber weniger fokussiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Rechteverwaltung für Services?', 2, '[{"text": "Sicherstellung der minimalen Zugriffsrechte", "correct": true, "because": "Schützt vor Missbrauch"}, {"text": "Maximierung der Benutzerinteraktion", "correct": false, "because": "Nicht relevant"}, {"text": "Vereinfachung der Installation", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch zu großzügige Rechtevergabe an einen Service entstehen?', 3, '[{"text": "Sicherheitslücke", "correct": true, "because": "Missbrauch wird erleichtert"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Rechte beeinflussen nicht die Geschwindigkeit"}, {"text": "Automatische Deaktivierung", "correct": false, "because": "Nicht standardmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kommando unter Linux zeigt die Rechte eines Service-Prozesses?', 2, '[{"text": "ls -l", "correct": true, "because": "Zeigt Dateirechte an"}, {"text": "top", "correct": false, "because": "Nur Prozessüberwachung"}, {"text": "chmod", "correct": false, "because": "Ändert Rechte, zeigt sie nicht"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte müssen bei der Rechteverwaltung von Services beachtet werden?', 4, '[{"text": "Zugriff auf Dateien", "correct": true, "because": "Erforderlich für Funktion"}, {"text": "Netzwerkberechtigungen", "correct": true, "because": "Für Kommunikation nötig"}, {"text": "Minimierung von Rechten", "correct": true, "because": "Erhöht Sicherheit"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können durch falsche Rechtevergabe an Services entstehen?', 3, '[{"text": "Zugriffsverweigerung", "correct": true, "because": "Fehlende Rechte blockieren"}, {"text": "Sicherheitsverletzungen", "correct": true, "because": "Zu viele Rechte gefährden"}, {"text": "Systeminstabilität", "correct": true, "because": "Fehlkonfiguration möglich"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden können zur Verwaltung von Service-Rechten genutzt werden?', 4, '[{"text": "Benutzerkonten", "correct": true, "because": "Definieren Zugriff"}, {"text": "Gruppenrichtlinien", "correct": true, "because": "Zentralisierte Steuerung"}, {"text": "Zugriffskontrolllisten (ACL)", "correct": true, "because": "Detaillierte Rechtevergabe"}, {"text": "Zufällige Zuweisung", "correct": false, "because": "Unsicher und unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte könnten einem Service zugewiesen werden?', 3, '[{"text": "Leserechte", "correct": true, "because": "Für Datenzugriff"}, {"text": "Schreibrechte", "correct": true, "because": "Für Datenänderung"}, {"text": "Ausführungsrechte", "correct": true, "because": "Für Programmstart"}, {"text": "Designrechte", "correct": false, "because": "Keine IT-Kategorie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine korrekte Rechteverwaltung für Services?', 3, '[{"text": "Erhöhte Sicherheit", "correct": true, "because": "Minimiert Risiken"}, {"text": "Bessere Kontrolle", "correct": true, "because": "Definiert Zugriff"}, {"text": "Vermeidung von Konflikten", "correct": true, "because": "Klarheit bei Ressourcennutzung"}, {"text": "Geringere Hardwareanforderungen", "correct": false, "because": "Unabhängig"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Service mit zu wenigen Rechten kann seine Aufgabe nicht erfüllen. b) Alle Services benötigen volle Administratorrechte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zu wenig Rechte ja, volle Rechte nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rechte können dynamisch an den Betriebszustand eines Services angepasst werden. b) Rechteverwaltung ist nur bei Netzwerkdiensten relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dynamische Anpassung ja, alle Services betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Least-Privilege-Prinzip reduziert Sicherheitsrisiken. b) Rechteänderungen erfordern nie einen Neustart des Services.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Least Privilege ja, Neustart oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Zu viele Rechte können einen Service angreifbar machen. b) Rechteverwaltung ist nur bei der Installation wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Angreifbarkeit ja, Verwaltung dauerhaft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Rechte sollten regelmäßig überprüft werden. b) Ein Service ohne Rechte kann keine Daten verarbeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überprüfung ja, minimale Rechte möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

